#!/usr/bin/env node
/**
 * Regenerate the bundled icon modules from the pinned OpenAI Apps SDK UI
 * source. The generated files are committed (they are build inputs), but the
 * pinned upstream is the single source of truth — never hand-edit path data.
 *
 * Usage:
 *   node scripts/generate-icon-data.mjs --source <dir>
 *
 * `--source` 指向包含图标定义的目录。每个文件导出一个
 * `{name, attrs:{viewBox,...}, shapes:[[tag, attrs], ...]}` 结构（OpenAI
 * apps-sdk-ui 的 `src/components/Icon/svg/*.ts`，或 Inform-UI 规整后的
 * `src/icons/definitions/*.ts`）。脚本按元素保留渲染所需的全部属性——
 * 只抓 `d` 会丢掉 fill-rule / clip-rule / stroke，导致 57 个字形画错。
 *
 * Produces:
 *   src/client/icons/icon-data.ts        内联集合（客户端包里）
 *   src/client/icons/icon-data-full.ts   全量集合（仅懒加载资产引用）
 *   src/client/icons/icon-names-full.ts  名字清单（内联，用于识别拼写错误）
 *   ICON-NAMES.md                        完整名单（给人 / SKILL grep 用）
 *
 * Upstream: https://github.com/openai/apps-sdk-ui @ 0f00143c7a639906f1621fe58e1b6be7b5bea46d (MIT).
 */
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { parseArgs } from 'node:util'

const { values } = parseArgs({
  options: {
    source: { type: 'string' },
    out: { type: 'string', default: 'src/client/icons' },
  },
  strict: true,
})

if (values.source === undefined) {
  console.error('usage: node scripts/generate-icon-data.mjs --source <icon-definitions-dir>')
  process.exit(1)
}

/** 内联集合：状态、箭头，以及构图真正会用到的那批计算/文档字形。 */
const INLINE = [
  'Check', 'CheckCircle', 'Info', 'InfoCircle', 'Warning', 'Error', 'X', 'Plus', 'Minus',
  'ArrowDown', 'ArrowUp', 'ArrowRight', 'ArrowLeft', 'ArrowCurvedRight',
  'Function', 'Functions', 'Operator', 'Atom', 'Nodes', 'Connect', 'Share', 'Branch', 'Grid', 'GridAlt', 'Stack',
  'Cube', 'Storage', 'Chart', 'Trending', 'Pulse', 'Speed', 'Timer', 'Clock', 'TableFilled',
  'Code', 'SquareCode', 'Terminal', 'File', 'FileCode', 'Folder', 'Folders', 'Link', 'Paperclip',
  'Lightbulb', 'Book', 'BookOpen', 'GraduationCap', 'Flask', 'Lab', 'Brain', 'Robot', 'Sparkles',
  'ShieldCheck', 'Lock', 'Globe', 'WebsiteNetwork', 'Search', 'MagnifyingGlassSearch',
  'PluginPuzzle', 'Settings', 'Bolt', 'Compass', 'Trash', 'Report',
]

const HEADER = `/**
 * OpenAI Apps SDK UI icons — https://github.com/openai/apps-sdk-ui
 * Pinned commit 0f00143c7a639906f1621fe58e1b6be7b5bea46d · MIT · Copyright 2025 OpenAI.
 * See THIRD_PARTY_NOTICES.md.
 *
 * Generated by scripts/generate-icon-data.mjs — do not hand-edit.
 */`

/** 渲染一个 shape 所需的属性；`d` 之外的都是保真关键项。 */
const SHAPE_ATTRS = ['d', 'fill-rule', 'clip-rule', 'stroke', 'stroke-width', 'stroke-linecap', 'stroke-linejoin', 'opacity', 'rx']
/** 可忠实渲染的标签；`g`（分组）与依赖 clipPath 的图标会被标记出来。 */
const RENDER_TAGS = new Set(['path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon'])

/** 把 JS 对象字面量安全地转成 JSON（源码里是 as const 的单引号对象）。 */
function parseObjectLiteral(text) {
  try {
    return Function(`"use strict";return (${text})`)()
  } catch {
    return undefined
  }
}

const catalogue = {}
const skipped = []
const problems = []

for (const file of readdirSync(values.source)) {
  if (!/\.(tsx?|jsx?)$/.test(file)) continue
  const name = file.replace(/\.(tsx?|jsx?)$/, '')
  const source = readFileSync(join(values.source, file), 'utf8')
  // 取 `export const X = {...} as const satisfies ...` 的对象体。
  const match = /export\s+const\s+\w+\s*=\s*(\{[\s\S]*?\})\s*as\s+const/.exec(source)
  if (match === null) { skipped.push(`${name}(无 export)`); continue }
  const definition = parseObjectLiteral(match[1])
  const shapes = Array.isArray(definition?.shapes) ? definition.shapes : []
  if (shapes.length === 0) { skipped.push(`${name}(无 shapes)`); continue }

  const rendered = []
  for (const entry of shapes) {
    if (!Array.isArray(entry) || typeof entry[0] !== 'string') continue
    const [tag, attrs] = entry
    if (!RENDER_TAGS.has(tag)) { problems.push(`${name}: <${tag}> 无法忠实渲染`); continue }
    const kept = { tag }
    for (const key of SHAPE_ATTRS) {
      if (attrs?.[key] !== undefined) kept[key] = String(attrs[key])
    }
    // path 需要 d；其他标签至少要有尺寸/半径/端点。
    const geometric = kept.d !== undefined
      || (tag !== 'path' && (attrs?.r !== undefined || attrs?.rx !== undefined || attrs?.x1 !== undefined))
    if (!geometric) { problems.push(`${name}: <${tag}> 缺几何属性`); continue }
    rendered.push(kept)
  }
  if (rendered.length === 0) { skipped.push(`${name}(无可渲染形状)`); continue }
  catalogue[name] = { viewBox: String(definition?.attrs?.viewBox ?? '0 0 24 24'), shapes: rendered }
}

const names = Object.keys(catalogue).sort()
const missingInline = INLINE.filter(name => catalogue[name] === undefined)
if (missingInline.length > 0) {
  console.error(`generate-icon-data: 内联名单在上游缺失: ${missingInline.join(', ')}`)
  console.error('  不再静默过滤——请修正 INLINE，或等上游补齐该字形。')
  process.exit(1)
}

const shapeLine = (s) => {
  const attrs = Object.entries(s)
    .filter(([k]) => k !== 'tag')
    .map(([k, v]) => `${JSON.stringify(k)}: ${JSON.stringify(v)}`)
    .join(', ')
  return `    { tag: '${s.tag}'${attrs === '' ? '' : `, ${attrs}`} },`
}

const body = (list) => list.map(name => `  ${name}: {\n    viewBox: '${catalogue[name].viewBox}',\n    shapes: [\n${catalogue[name].shapes.map(shapeLine).join('\n')}\n    ],\n  },`).join('\n')

const TYPE_BLOCK = `export interface BundledIcon {
  viewBox: string
  /** 渲染单元：tag + 该 tag 需要的属性（含 fill-rule 等保真项）。 */
  shapes: IconShape[]
}

export interface IconShape {
  tag: string
  d?: string
  'fill-rule'?: 'nonzero' | 'evenodd'
  'clip-rule'?: 'nonzero' | 'evenodd'
  stroke?: string
  'stroke-width'?: string
  'stroke-linecap'?: 'butt' | 'round' | 'square'
  'stroke-linejoin'?: 'miter' | 'round' | 'bevel'
  opacity?: string
  rx?: string
}`

writeFileSync(join(values.out, 'icon-data-full.ts'),
  `${HEADER}\n/**\n * 全量字形（${names.length} 个）。只有懒加载资产入口引用它，不进入客户端包。\n */\n${TYPE_BLOCK}\n\nexport const ICONS_FULL: Readonly<Record<string, BundledIcon>> = {\n${body(names)}\n}\n`)

writeFileSync(join(values.out, 'icon-data.ts'),
  `${HEADER}\n/**\n * 内联集合（${INLINE.length} 个）：随客户端包发布，常见构图无需下载即可渲染。\n * 其余字形见 icon-data-full.ts，经 lib/assets/icons.js 按需载入。\n */\n${TYPE_BLOCK}\n\nexport const ICONS: Readonly<Record<string, BundledIcon>> = {\n${body(INLINE)}\n}\n`)

writeFileSync(join(values.out, 'icon-names-full.ts'),
  `${HEADER}\n/**\n * 全部规范名（${names.length}）。只内联名字，好让渲染器区分「拼错」和「还没下载」：\n * 不在这里的名字立刻走中性圆点兜底，不会触发 900 kB 的字形包下载。\n */\nexport const ICON_NAMES_FULL: readonly string[] = ${JSON.stringify(names)}\n`)

// ICON-NAMES.md 也由脚本产出，避免手抄漂移（review #6）。
// 写到仓库根：out 默认是 src/client/icons，往上一层才是仓库根。
const repoRoot = join(values.out, '..', '..', '..')
writeFileSync(join(repoRoot, 'ICON-NAMES.md'), `# 图标名清单（全量 ${names.length} 个）

> 本文件由 \`scripts/generate-icon-data.mjs\` 生成，请勿手改。
> 来源：OpenAI Apps SDK UI，commit \`0f00143c7a639906f1621fe58e1b6be7b5bea46d\`，MIT。

\`icon\` 节点接受下列任意名字（区分大小写）。未知名字渲染为中性圆点，
不会丢块，也不会触发下载。

## 内联（${INLINE.length} 个，无需下载）

\`\`\`text
${INLINE.join(' ')}
\`\`\`

## 按需载入（${names.length - INLINE.length} 个）

首次用到非内联名字时，会一次性拉取 \`lib/assets/icons.js\`（约 900 kB），
此后本页全部可用。

\`\`\`text
${names.filter(n => !INLINE.includes(n)).join(' ')}
\`\`\`
`)

console.log(`icons: ${names.length} total / ${INLINE.length} inline / ${names.length - INLINE.length} lazy`)
console.log(`skipped: ${skipped.length}${skipped.length > 0 ? `（${skipped.slice(0, 8).join('; ')}${skipped.length > 8 ? '…' : ''}）` : ''}`)
if (problems.length > 0) console.log(`problems: ${problems.length}（${problems.slice(0, 5).join('; ')}${problems.length > 5 ? '…' : ''}）`)
